                                        >
                                            <Circle size={18} />
                                        </button>
                                        <div onClick={() => router.push(`/para/projects?id=${task.projectId}`)}>
                                            <p className="text-[14px] text-primary font-medium group-hover:text-accent transition-colors">{task.title}</p>
                                            <p className="text-[12px] text-secondary">{task.projectName}</p>
                                        </div>
                                    </div>
                                    <div className="text-[11px] text-text-muted font-mono bg-subtle px-2 py-0.5 rounded-[4px] border border-border/50">
                                        {task.dueDate || 'Today'}
                                    </div>
                                </div>
                            ))}
                        {projects.every(p => (p.tasks || []).every(t => t.completed)) && (
                            <p className="text-sm text-text-muted italic py-2 px-3">No tasks left! You&apos;re crushing it. Γ£¿</p>
                        )}
                    </div>
                </div>

            </div>

            {/* Right Column (Side Panel) */}
            <div className="lg:w-[320px] shrink-0 border-t lg:border-t-0 lg:border-l border-border pt-8 lg:pt-0 lg:pl-8 space-y-10">

                {/* Quiet AI Context Panel */}
                <motion.div
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.2 }}
                    className="space-y-4"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles size={14} className="text-accent" />
                        <h2 className="text-[11px] font-semibold text-text-muted uppercase tracking-[0.06em]">Insights</h2>
                    </div>

                    <div className="p-4 bg-accent-light/30 border-l-2 border-l-accent rounded-r-card text-sm space-y-3">
                        <p className="text-primary leading-relaxed text-[13px]">
                            You captured 3 notes about &quot;Traction&quot; yesterday. Want me to draft the Investor Deck slides?
                        </p>
                        <button 
                            onClick={() => {
                                const { addProjectTask } = useDemoStore.getState();
                                addProjectTask('1', 'Draft slide: Key Traction Metrics');
                                addProjectTask('1', 'Draft slide: Growth Projections');
