                            <div key={habit.id} className="group relative">
                                <div 
                                    onClick={() => {
                                        const { addHabitEntry } = useDemoStore.getState();
                                        addHabitEntry(habit.id);
                                        toast.success(`Toggled habit: ${habit.name}`);
                                    }}
                                    className={cn(
                                        "w-full aspect-square rounded-[4px] border transition-colors flex items-center justify-center cursor-pointer",
                                        i < 3 || habit.streak > 0 // Show first 3 or active streak as completed for mock purposes
