                            className="relative w-full max-w-md bg-card border border-border rounded-modal shadow-modal overflow-hidden pointer-events-auto"
                        >
                            <div className="p-6 border-b border-border flex justify-between items-center">
                                <h2 className="text-lg font-display text-primary">New Project</h2>
                                <button onClick={() => setIsNewProjectModalOpen(false)} className="text-text-muted hover:text-primary transition-colors"><X size={20} /></button>
                            </div>
                            <div className="p-6 space-y-4">
                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">Project Title</label>
                                    <input 
                                        type="text" 
                                        value={newProjectTitle}
                                        onChange={(e) => setNewProjectTitle(e.target.value)}
                                        placeholder="e.g. Website Redesign"
                                        className="w-full h-10 px-3 bg-subtle border border-border rounded-input text-sm focus:outline-none focus:border-accent"
                                    />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">Initial Status</label>
                                    <div className="flex gap-2">
                                        {(['Active', 'Paused'] as const).map(status => (
                                            <button
                                                key={status}
                                                onClick={() => setNewProjectStatus(status)}
                                                className={cn(
                                                    "flex-1 py-2 text-xs font-medium rounded-button border transition-all",
                                                    newProjectStatus === status 
                                                        ? "bg-accent/10 border-accent text-accent" 
                                                        : "bg-transparent border-border text-text-muted hover:border-border-strong"
                                                )}
                                            >
                                                {status}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                            <div className="p-6 pt-0">
                                <Button 
                                    className="w-full" 
                                    disabled={!newProjectTitle.trim()}
                                    onClick={() => {
                                        addProject({
                                            title: newProjectTitle,
                                            status: newProjectStatus,
                                            progress: 0,
                                            dueDate: null
                                        });
                                        setIsNewProjectModalOpen(false);
                                        setNewProjectTitle('');
                                    }}
                                >
                                    Create Project
                                </Button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
            {/* New Task Modal */}
            <AnimatePresence>
                {isNewTaskModalOpen && (
                    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setIsNewTaskModalOpen(false)}
                            className="absolute inset-0 bg-zinc-900/60 backdrop-blur-sm pointer-events-auto"
                        />
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95, y: 10 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.95, y: 10 }}
                            className="relative w-full max-w-md bg-card border border-border rounded-modal shadow-modal overflow-hidden pointer-events-auto"
                        >
                            <div className="p-6 border-b border-border flex justify-between items-center">
                                <h2 className="text-lg font-display text-primary">New Task in {selectedProject?.title}</h2>
                                <button onClick={() => setIsNewTaskModalOpen(false)} className="text-text-muted hover:text-primary transition-colors"><X size={20} /></button>
                            </div>
                            <div className="p-6 space-y-4">
                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">Task Title</label>
                                    <input 
                                        type="text" 
                                        value={newTaskTitle}
                                        onChange={(e) => setNewTaskTitle(e.target.value)}
                                        placeholder="e.g. Schedule meeting with stakeholders"
                                        className="w-full h-10 px-3 bg-subtle border border-border rounded-input text-sm focus:outline-none focus:border-accent"
                                        autoFocus
                                    />
                                </div>
                            </div>
                            <div className="p-6 pt-0">
                                <Button 
                                    className="w-full" 
                                    disabled={!newTaskTitle.trim()}
                                    onClick={() => {
                                        if (selectedProject) {
                                            addProjectTask(selectedProject.id, newTaskTitle);
                                            setIsNewTaskModalOpen(false);
                                            setNewTaskTitle('');
                                        }
                                    }}
                                >
                                    Add Task
                                </Button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

'use client';

import { useState, useEffect, useMemo, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import { useNeyroStore } from '@mobile/store/useNeyroStore';
import { Resource } from '@mobile/database/schema';
import { toast } from 'sonner';
import {
    Search,
    Sparkles,
    Archive,
    Link as LinkIcon,
    FileText,
    Image as ImageIcon,
    Mic,
    MoreHorizontal,
    CheckCircle2,
    Library
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/Button';

// Mock AI Tags usage for now since DB might be empty
const getResourceTags = (r: Resource): string[] => {
    if (r.aiTags) {
        try {
            return JSON.parse(r.aiTags);
        } catch (e) { return []; }
    }
    // Fallback logic for demo/transition if no tags
    const title = (r.title || '').toLowerCase();
    if (title.includes('design') || title.includes('ui') || title.includes('ux')) return ['Design'];
    if (title.includes('code') || title.includes('dev') || title.includes('api')) return ['Development'];
    if (title.includes('music') || title.includes('guitar')) return ['Music'];
    return ['Unsorted'];
};

function ResourcesPageContent() {
    const loadData = useNeyroStore((state) => state.loadData);
    const resources = useNeyroStore((state) => state.resources) || [];
    const addResource = useNeyroStore((state) => state.addResource);
    const addTask = useNeyroStore((state) => state.addTask);

    const [showArchiveSuggestions, setShowArchiveSuggestions] = useState(true);
    const [isCleanupMode, setIsCleanupMode] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [newItemTitle, setNewItemTitle] = useState('');
    const [newItemUrl, setNewItemUrl] = useState('');

    // Initialize now once on mount to keep render pure
    const [now] = useState(() => Date.now());
    const [activeTab, setActiveTab] = useState<'all' | 'link' | 'audio' | 'image' | 'pdf'>('all');
    const searchParams = useSearchParams();
    const urlQuery = searchParams.get('search') || '';
    const [localSearchQuery, setLocalSearchQuery] = useState<string | null>(null);
    const searchQuery = localSearchQuery !== null ? localSearchQuery : urlQuery;

    useEffect(() => {
        // Initial data fetch
        loadData();
    }, [loadData]);

    // 1. Filter by Type & Search
    const filteredResources = useMemo(() => {
        return resources.filter((r: Resource) => {
            if (r.isArchived) return false; // Hide archived by default

            const matchesSearch = (r.title || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
                (r.summary && r.summary.toLowerCase().includes(searchQuery.toLowerCase()));
            const matchesType = activeTab === 'all' || r.type === activeTab || (activeTab === 'pdf' && r.type === 'note'); // simplified mapping

            if (isCleanupMode) {
                const threshold = now - (30 * 24 * 60 * 60 * 1000);
                return matchesSearch && matchesType && r.updatedAt < threshold;
            }

            return matchesSearch && matchesType;
        });
    }, [resources, searchQuery, activeTab, isCleanupMode, now]); // Added now to dependency array

    // 2. Group by Topic Cluster
    const clusters = useMemo(() => {
        const groups: Record<string, Resource[]> = {};

        filteredResources.forEach((r: Resource) => {
            const tags = getResourceTags(r);
            const primaryTag = tags[0] || 'Unsorted';

            if (!groups[primaryTag]) groups[primaryTag] = [];
            groups[primaryTag].push(r);
        });

        return groups;
    }, [filteredResources]);

    // 3. Identify Archive Suggestions (Old items)
    const archiveSuggestions = useMemo(() => {
        const threshold = now - (30 * 24 * 60 * 60 * 1000); // 30 days
        return resources.filter((r) => !r.isArchived && r.updatedAt < threshold).slice(0, 3);
    }, [resources, now]); // Added now to dependency array

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItemTitle.trim()) return;

        // Simple creation for now - in real app would invoke AI scraper for URL
        await addResource(newItemTitle, false, null, 'link', newItemUrl);
        setNewItemTitle('');
        setNewItemUrl('');
        setIsCreating(false);
    };

    const handleMakeActionable = async (resource: Resource) => {
        // Create a task linked to this resource
        const taskTitle = `Review: ${resource.title}`;
        // Find an active project to link to, or default to first one
        const activeProjects = useNeyroStore.getState().activeProjects;
        const targetProjectId = activeProjects[0]?.id;

        if (targetProjectId) {
            await addTask(taskTitle, targetProjectId, 'project');
            toast.success(`Task created in ${activeProjects[0].title}: "${taskTitle}"`);
        } else {
            // Fallback to inbox if no projects
            await addTask(taskTitle, 'inbox', 'project');
            toast.success(`Task created in Inbox: "${taskTitle}"`);
        }
    };

    const getTypeIcon = (type: string | null) => {
        switch (type) {
            case 'audio': return <Mic className="w-4 h-4 text-purple-400" />;
            case 'image': return <ImageIcon className="w-4 h-4 text-pink-400" />;
            case 'pdf': return <FileText className="w-4 h-4 text-orange-400" />;
            case 'link':
            default: return <LinkIcon className="w-4 h-4 text-blue-400" />;
        }
    };

    return (
        <div className="flex flex-col h-full overflow-hidden">
            {/* Header */}
            <div className="flex-none p-8 pb-0 space-y-6">
                <div className="flex items-end justify-between">
                    <div>
                        <h1 className="text-4xl font-black text-white tracking-tight flex items-center gap-3">
                            <Library className="w-8 h-8 text-neutral-400" />
                            Knowledge Vault
                        </h1>
                        <p className="text-neutral-400 mt-2">
                           Global repository for your interests, research, and captured content.
                        </p>
                    </div>
                    <Button
                        onClick={() => setIsCreating(true)}
                        className="bg-orange-500 hover:bg-orange-600 text-white shadow-[0_0_15px_rgba(255,106,0,0.3)]"
                    >
                        + Add Resource
                    </Button>
                </div>

                {/* Controls */}
                <div className="flex items-center gap-4">
                    <div className="relative flex-1 max-w-xl">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-500" />
                        <input
                            value={searchQuery}
                            onChange={(e) => setLocalSearchQuery(e.target.value)}
                            placeholder="Search by title, summary, or tag..."
                            className="w-full bg-neutral-900/50 border border-white/10 rounded-xl pl-10 pr-4 py-2.5 text-sm text-white focus:outline-none focus:border-primary/50 transition-all"
                        />
                    </div>

                    <div className="flex bg-neutral-900/50 p-1 rounded-lg border border-white/5">
                        {['all', 'link', 'audio', 'image', 'pdf'].map((tab) => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab as 'all' | 'link' | 'audio' | 'image' | 'pdf')}
                                className={cn(
                                    "px-4 py-1.5 rounded-md text-sm font-medium transition-all capitalize",
                                    activeTab === tab
                                        ? "bg-white/10 text-white shadow-sm"
                                        : "text-neutral-500 hover:text-neutral-300"
                                )}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Scrollable Content */}
            <div className="flex-1 overflow-y-auto p-8 space-y-8">

                {/* Archive Suggestions */}
                {showArchiveSuggestions && archiveSuggestions.length > 0 && (
                    <div className="bg-gradient-to-r from-purple-900/20 to-blue-900/20 border border-white/10 rounded-2xl p-4 flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center">
                                <Sparkles className="w-5 h-5 text-purple-400" />
                            </div>
                            <div>
                                <h3 className="text-white font-bold text-sm">Clean up your Vault?</h3>
                                <p className="text-neutral-400 text-xs">
                                    We found {archiveSuggestions.length} items you haven&apos;t touched in a while.
                                </p>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <Button variant="ghost" size="sm" onClick={() => setShowArchiveSuggestions(false)}>Dismiss</Button>
                            <Button 
                                size="sm" 
                                onClick={() => {
                                    setIsCleanupMode(true);
                                    setActiveTab('all');
                                    setLocalSearchQuery('');
                                }} 
                                className={cn(
                                    "text-white border border-white/5",
                                    isCleanupMode ? "bg-purple-500/40" : "bg-white/10 hover:bg-white/20"
                                )}
                            >
                                {isCleanupMode ? "Viewing Candidates" : "Review Candidates"}
                            </Button>
                            {isCleanupMode && (
                                <Button 
                                    size="sm" 
                                    variant="ghost" 
                                    onClick={() => setIsCleanupMode(false)}
                                    className="text-white/60 hover:text-white"
                                >
                                    Reset
                                </Button>
                            )}
                        </div>
                    </div>
                )}

                {/* Topic Clusters */}
                {Object.entries(clusters).map(([topic, items]) => (
                    <div key={topic} className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <div className="flex items-center gap-2 mb-4">
                            <h2 className="text-lg font-bold text-white max-w-max bg-gradient-to-r from-neutral-800 to-transparent px-3 py-1 rounded-full border border-white/5">
                                {topic}
                            </h2>
                            <div className="h-px bg-white/5 flex-1" />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {items.map((item) => (
                                <div
                                    key={item.id}
                                    className="group flex flex-col bg-neutral-900/30 hover:bg-neutral-900/60 border border-white/5 hover:border-white/10 rounded-xl p-4 transition-all duration-200"
                                >
                                    <div className="flex items-start justify-between mb-3">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-white/5 flex items-center justify-center group-hover:bg-primary/20 transition-colors">
                                                {getTypeIcon(item.type)}
                                            </div>
                                            <div className="flex flex-col">
                                                <h3 className="text-sm font-semibold text-white line-clamp-1 group-hover:text-primary transition-colors">
                                                    {item.title}
                                                </h3>
                                                <span className="text-[10px] text-neutral-500 flex items-center gap-1">
                                                    {new Date(item.createdAt).toLocaleDateString()}
                                                </span>
                                            </div>
                                        </div>
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-6 w-6 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <MoreHorizontal className="w-4 h-4 text-neutral-400" />
                                        </Button>
                                    </div>

                                    {/* Smart Summary */}
                                    {item.summary ? (
                                        <div className="bg-white/5 rounded-lg p-2 mb-3">
                                            <div className="flex items-center gap-1 mb-1">
                                                <Sparkles className="w-3 h-3 text-secondary" />
                                                <span className="text-[10px] font-bold text-secondary uppercase tracking-wider">Smart Summary</span>
                                            </div>
                                            <p className="text-xs text-neutral-400 line-clamp-2 leading-relaxed">
                                                {item.summary}
                                            </p>
                                        </div>
                                    ) : null}

                                    {/* Action Footer */}
                                    <div className="mt-auto pt-3 border-t border-white/5 flex items-center justify-between gap-2 opacity-50 group-hover:opacity-100 transition-opacity">
                                        <div className="flex gap-2">
                                            {item.sourceUrl && (
                                                <a
                                                    href={item.sourceUrl}
                                                    target="_blank"
                                                    rel="noreferrer"
                                                    className="text-[10px] text-neutral-400 hover:text-white flex items-center gap-1"
                                                >
                                                    <LinkIcon className="w-3 h-3" />
                                                </a>
                                            )}
                                            <button className="text-[10px] text-neutral-400 hover:text-white flex items-center gap-1" title="Share with team">
                                                <MoreHorizontal className="w-3 h-3" />
                                            </button>
                                        </div>
                                        <button
                                            onClick={() => handleMakeActionable(item)}
                                            className="ml-auto text-[10px] font-medium text-primary hover:text-orange-400 flex items-center gap-1 bg-primary/10 hover:bg-primary/20 px-2 py-1 rounded-md transition-colors"
                                        >
                                            <CheckCircle2 className="w-3 h-3" />
                                            Make Actionable
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Creation Modal */}
            {isCreating && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in">
                    <div className="w-full max-w-md bg-neutral-900 border border-white/10 rounded-2xl p-6 shadow-2xl">
                        <h2 className="text-xl font-bold text-white mb-4">Add to Vault</h2>
                        <form onSubmit={handleCreate} className="space-y-4">
                            <div>
                                <label className="block text-sm text-neutral-400 mb-1">Title</label>
                                <input
                                    autoFocus
                                    type="text"
                                    value={newItemTitle}
                                    onChange={(e) => setNewItemTitle(e.target.value)}
                                    placeholder="e.g. Design Principles 2024"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-primary/50"
                                />
                            </div>
                            <div>
                                <label className="block text-sm text-neutral-400 mb-1">URL (Optional)</label>
                                <input
                                    type="text"
                                    value={newItemUrl}
                                    onChange={(e) => setNewItemUrl(e.target.value)}
                                    placeholder="https://..."
                                    className="w-full bg-black/50 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-primary/50"
                                />
                            </div>
                            <div className="flex justify-end gap-3 pt-2">
                                <Button
                                    type="button"
                                    onClick={() => setIsCreating(false)}
                                    className="bg-transparent hover:bg-white/5 text-neutral-400"
                                >
                                    Cancel
                                </Button>
                                <Button
                                    type="submit"
                                    disabled={!newItemTitle.trim()}
                                    className="bg-orange-500 hover:bg-orange-600 text-white"
                                >
                                    Save to Vault
                                </Button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

export default function ResourcesPage() {
    return (
        <Suspense fallback={<div className="p-8 text-neutral-500">Loading resources...</div>}>
            <ResourcesPageContent />
        </Suspense>
    );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Inbox, CalendarRange, FolderEdit, Activity, Target, ArrowRight, ArrowLeft } from 'lucide-react';
import { useDemoStore } from '@/store/demo-store';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import React from 'react';
import { Button } from '@/components/ui/Button';

const STEPS = [
    { id: 'inbox', title: 'Clear Inbox', icon: Inbox, desc: 'Process all active captures' },
    { id: 'reflection', title: 'Reflect', icon: CalendarRange, desc: 'Review the past 7 days' },
    { id: 'projects', title: 'Projects', icon: FolderEdit, desc: 'Update statuses & tasks' },
    { id: 'areas', title: 'Areas', icon: Activity, desc: 'Assess health & standards' },
    { id: 'planning', title: 'Plan', icon: Target, desc: 'Set intentions for the week' }
];

export default function ReviewPage() {
    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [isComplete, setIsComplete] = useState(false);
    const { captures, projects, areas, setMomentumScore, momentumScore } = useDemoStore();

    const currentStep = STEPS[currentStepIndex];

    const nextStep = () => {
        if (currentStepIndex === STEPS.length - 1) {
            setIsComplete(true);
            setMomentumScore(momentumScore + 50);
        } else {
            setCurrentStepIndex(prev => prev + 1);
        }
    };

    const prevStep = () => {
        if (currentStepIndex > 0) {
            setCurrentStepIndex(prev => prev - 1);
        }
    };

    if (isComplete) {
        return (
            <div className="h-[calc(100vh-8rem)] flex items-center justify-center animate-in fade-in duration-700">
                <div className="text-center max-w-[480px]">
                    <motion.div
                        initial={{ scale: 0.9, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        transition={{ type: 'spring', damping: 20 }}
                        className="w-16 h-16 bg-accent-light/10 text-accent rounded-full flex items-center justify-center mx-auto mb-8"
                    >
                        <Target size={32} />
                    </motion.div>

                    <h1 className="text-[40px] font-display font-bold text-primary mb-4 tracking-tight leading-tight">Review Complete</h1>
                    <p className="text-[17px] text-secondary mb-10 leading-relaxed">
                        You&apos;re locked in and ready for the week. You gained <strong className="text-accent font-medium">+50 Momentum</strong>.
                    </p>

                    <Button
                        size="lg"
                        variant="primary"
                        className="w-full text-[15px] h-14"
                        onClick={() => window.location.href = '/dashboard'}
                    >
                        Return to Dashboard
                    </Button>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-[640px] mx-auto h-full flex flex-col pt-12 pb-24 px-8 min-h-[calc(100vh-64px)] animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-forwards">

            {/* 5-Dot Progress Tracker */}
            <div className="flex items-center justify-center gap-3 mb-16">
                {STEPS.map((step, idx) => {
                    const isActive = idx === currentStepIndex;
                    const isPast = idx < currentStepIndex;
                    return (
                        <div key={step.id} className="flex items-center gap-3">
                            <div className={cn(
                                "w-2.5 h-2.5 rounded-full transition-all duration-300",
                                isActive ? "bg-accent scale-125 ring-4 ring-accent-light/20" : isPast ? "bg-accent/40" : "bg-subtle border border-border"
                            )} />
                            {idx < STEPS.length - 1 && (
                                <div className={cn(
                                    "h-[1px] w-6 transition-colors duration-300",
                                    isPast ? "bg-accent/40" : "bg-border/60"
                                )} />
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Content Area */}
            <div className="flex-1 relative">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={currentStep.id}
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: -20 }}
                        transition={{ duration: 0.3, ease: 'easeOut' }}
                        className="absolute inset-0 pb-32"
                    >
                        <div className="mb-12">
                            <h2 className="text-[40px] font-display font-medium text-primary tracking-tight leading-tight mb-3">
                                {currentStep.title}
                            </h2>
                            <p className="text-[17px] text-text-muted">{currentStep.desc}</p>
                        </div>

                        {/* Step Details */}
                        <div className="space-y-6">
                            {currentStep.id === 'inbox' && (
                                <div className="space-y-6">
                                    <div className="text-[15px] text-secondary leading-relaxed">
                                        You have <strong className="text-primary font-medium">{captures.length}</strong> items in your inbox. Review them and convert to projects, resources, or archive.
                                    </div>
                                    <div className="grid grid-cols-1 gap-4">
                                        {captures.slice(0, 4).map(capture => (
                                            <div key={capture.id} className="p-5 border border-border bg-transparent rounded-card group hover:border-accent/30 transition-colors">
                                                <p className="text-primary text-[15px] mb-4 leading-relaxed">"{capture.content}"</p>
                                                <div className="flex gap-3">
