'use client';

import React, { useState } from 'react';
import { ArrowRight, ArrowLeft, CheckCircle2, X, Sparkles } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from './ui/Button';
import { useNeyroStore } from '@mobile/store/useNeyroStore';
import { ClassifierService } from '@/services/classifierService';
import { useTodayList } from '@/hooks/useTodayList';
import { cn } from '@/lib/utils';

interface ProcessingWizardProps {
    item: { id: string; content: string; createdAt: number };
    onComplete: () => void;
    onCancel: () => void;
}

type WizardStep = 'clarify' | 'categorize' | 'plan' | 'commit';

export function ProcessingWizard({ item, onComplete, onCancel }: ProcessingWizardProps) {
    const [step, setStep] = useState<WizardStep>('clarify');
    const [clarified, setClarified] = useState(item.content);
    const [category, setCategory] = useState<'project' | 'area' | 'resource' | 'archive' | null>(null);
    const [targetId, setTargetId] = useState<string | undefined>();
    const [dueDate, setDueDate] = useState<string>('');
    const [timeEstimate, setTimeEstimate] = useState<number>(30);
    const [energyLevel, setEnergyLevel] = useState<'low' | 'medium' | 'high'>('medium');
    const [commitment, setCommitment] = useState<'today' | 'this-week' | 'someday' | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);

    // @ts-ignore
    const activeProjects = useNeyroStore((state: any) => state.activeProjects || []);
    // @ts-ignore
    const areas = useNeyroStore((state: any) => state.areas || []);
    // @ts-ignore
    const classifyItem = useNeyroStore((state: any) => state.classifyItem);
    // @ts-ignore
    const loadData = useNeyroStore((state: any) => state.loadData);
    const { addToToday } = useTodayList();

    const handleAIEnhance = async () => {
        setIsProcessing(true);
        try {
            const classification = await ClassifierService.classify(clarified, {
                projects: activeProjects,
                areas: areas,
            });

            if (classification.destination !== 'archive') {
                setCategory(classification.destination);
                setTargetId(classification.targetId);
            }
        } catch (e) {
            console.error('AI enhancement failed:', e);
        } finally {
            setIsProcessing(false);
        }
    };

    const handleFinish = async () => {
        if (!category) return;

        setIsProcessing(true);
        try {
            await classifyItem(item.id, category, targetId);

            // Add to Today list if commitment is 'today'
            if (commitment === 'today') {
                addToToday({
                    id: `today_${item.id}_${Date.now()}`,
                    title: clarified,
                    priority: energyLevel === 'high' ? 'high' : energyLevel === 'medium' ? 'medium' : 'low',
                    timeEstimate,
                    energyLevel,
                    sourceType: 'inbox',
                    sourceId: item.id,
                    dueDate: dueDate || undefined,
                    tags: [],
                });
            }

            await loadData();
            onComplete();
        } catch (e) {
            console.error('Failed to process:', e);
        } finally {
            setIsProcessing(false);
        }
    };

    const steps: WizardStep[] = ['clarify', 'categorize', 'plan', 'commit'];
    const currentStepIndex = steps.indexOf(step);

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="bg-[#1C1C1E] border border-white/10 rounded-2xl p-8 max-w-2xl w-full max-h-[90vh] overflow-y-auto"
            >
                {/* Progress */}
                <div className="flex items-center gap-2 mb-6">
                    {steps.map((s, i) => (
                        <React.Fragment key={s}>
                            <div className={cn(
                                "size-8 rounded-full flex items-center justify-center text-sm font-bold transition-all",
                                i <= currentStepIndex ? "bg-primary text-white" : "bg-white/10 text-neutral-500"
                            )}>
                                {i < currentStepIndex ? <CheckCircle2 className="size-5" /> : i + 1}
                            </div>
                            {i < steps.length - 1 && (
                                <div className={cn(
                                    "h-1 flex-1 rounded-full transition-all",
                                    i < currentStepIndex ? "bg-primary" : "bg-white/10"
                                )} />
                            )}
                        </React.Fragment>
                    ))}
                </div>

                {/* Step Content */}
                <AnimatePresence mode="wait">
                    {step === 'clarify' && (
                        <motion.div
                            key="clarify"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                        >
                            <h3 className="text-2xl font-bold text-white mb-2">Clarify</h3>
                            <p className="text-neutral-400 mb-4">Refine and clarify what this item means</p>
                            <textarea
                                value={clarified}
                                onChange={(e) => setClarified(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-white min-h-[150px] focus:outline-none focus:border-primary/50"
                                placeholder="What does this really mean?"
                            />
                            <Button
                                onClick={handleAIEnhance}
                                disabled={isProcessing}
                                variant="ghost"
                                className="mt-3"
                            >
                                <Sparkles className="size-4 mr-2" />
                                {isProcessing ? 'AI is thinking...' : 'Enhance with AI'}
                            </Button>
                        </motion.div>
                    )}

                    {step === 'categorize' && (
                        <motion.div
                            key="categorize"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                        >
                            <h3 className="text-2xl font-bold text-white mb-2">Categorize</h3>
                            <p className="text-neutral-400 mb-4">Where does this belong?</p>
                            <div className="grid grid-cols-2 gap-3">
                                {[
                                    { value: 'project' as const, label: 'Project', icon: '≡ƒôü', desc: 'Actionable goal' },
                                    { value: 'area' as const, label: 'Area', icon: '≡ƒôé', desc: 'Ongoing responsibility' },
                                    { value: 'resource' as const, label: 'Resource', icon: '≡ƒôÜ', desc: 'Reference material' },
                                    { value: 'archive' as const, label: 'Archive', icon: '≡ƒùä∩╕Å', desc: 'Completed/done' },
                                ].map(opt => (
                                    <button
                                        key={opt.value}
                                        onClick={() => setCategory(opt.value)}
                                        className={cn(
                                            "p-4 rounded-xl border-2 text-left transition-all",
                                            category === opt.value
                                                ? "border-primary bg-primary/20"
                                                : "border-white/10 hover:border-white/20"
                                        )}
                                    >
                                        <div className="text-2xl mb-2">{opt.icon}</div>
                                        <div className="font-semibold text-white">{opt.label}</div>
                                        <div className="text-xs text-neutral-400">{opt.desc}</div>
                                    </button>
                                ))}
                            </div>
                            {category && category !== 'archive' && (
                                <div className="mt-4">
                                    <p className="text-sm text-neutral-400 mb-2">Select target:</p>
                                    {category === 'project' && (
                                        <select
                                            value={targetId || ''}
                                            onChange={(e) => setTargetId(e.target.value || undefined)}
                                            className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-white"
                                        >
                                            <option value="">New Project</option>
                                            {activeProjects.map((p: any) => (
                                                <option key={p.id} value={p.id}>{p.title}</option>
                                            ))}
                                        </select>
                                    )}
                                    {category === 'area' && (
                                        <select
                                            value={targetId || ''}
                                            onChange={(e) => setTargetId(e.target.value || undefined)}
                                            className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-white"
                                        >
                                            <option value="">New Area</option>
                                            {areas.map((a: any) => (
                                                <option key={a.id} value={a.id}>{a.title}</option>
                                            ))}
                                        </select>
                                    )}
                                </div>
                            )}
                        </motion.div>
                    )}

                    {step === 'plan' && (
                        <motion.div
                            key="plan"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                        >
                            <h3 className="text-2xl font-bold text-white mb-2">Plan</h3>
                            <p className="text-neutral-400 mb-4">Add details for execution</p>
                            <div className="space-y-4">
                                <div>
                                    <label className="text-sm text-neutral-400 mb-2 block">Due Date</label>
                                    <input
                                        type="date"
                                        value={dueDate}
                                        onChange={(e) => setDueDate(e.target.value)}
                                        className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-white"
                                    />
                                </div>
                                <div>
                                    <label className="text-sm text-neutral-400 mb-2 block">Time Estimate (minutes)</label>
                                    <input
                                        type="number"
                                        value={timeEstimate}
                                        onChange={(e) => setTimeEstimate(parseInt(e.target.value) || 30)}
                                        className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-white"
                                        min="5"
                                        step="5"
                                    />
                                </div>
                                <div>
                                    <label className="text-sm text-neutral-400 mb-2 block">Energy Level</label>
                                    <div className="flex gap-2">
                                        {(['low', 'medium', 'high'] as const).map(level => (
                                            <button
                                                key={level}
                                                onClick={() => setEnergyLevel(level)}
                                                className={cn(
                                                    "flex-1 py-2 rounded-lg border-2 capitalize",
                                                    energyLevel === level
                                                        ? "border-primary bg-primary/20 text-primary"
                                                        : "border-white/10 text-neutral-400"
                                                )}
                                            >
                                                {level}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </motion.div>
                    )}

                    {step === 'commit' && (
                        <motion.div
                            key="commit"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                        >
                            <h3 className="text-2xl font-bold text-white mb-2">Commit</h3>
                            <p className="text-neutral-400 mb-4">When will you do this?</p>
                            <div className="space-y-3">
                                {[
                                    { value: 'today' as const, label: 'Today', desc: 'Do this today' },
                                    { value: 'this-week' as const, label: 'This Week', desc: 'Within 7 days' },
                                    { value: 'someday' as const, label: 'Someday', desc: 'No specific timeline' },
                                ].map(opt => (
                                    <button
                                        key={opt.value}
                                        onClick={() => setCommitment(opt.value)}
                                        className={cn(
                                            "w-full p-4 rounded-xl border-2 text-left transition-all",
                                            commitment === opt.value
                                                ? "border-primary bg-primary/20"
                                                : "border-white/10 hover:border-white/20"
                                        )}
                                    >
                                        <div className="font-semibold text-white">{opt.label}</div>
                                        <div className="text-xs text-neutral-400">{opt.desc}</div>
                                    </button>
                                ))}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Navigation */}
                <div className="flex items-center justify-between mt-6 pt-6 border-t border-white/10">
                    <Button
                        onClick={currentStepIndex > 0 ? () => setStep(steps[currentStepIndex - 1]) : onCancel}
                        variant="ghost"
                    >
                        {currentStepIndex > 0 ? (
                            <>
                                <ArrowLeft className="size-4 mr-2" />
                                Back
                            </>
                        ) : (
                            'Cancel'
                        )}
                    </Button>
                    <Button
                        onClick={currentStepIndex < steps.length - 1 
                            ? () => setStep(steps[currentStepIndex + 1])
                            : handleFinish
                        }
                        disabled={isProcessing || (step === 'categorize' && !category) || (step === 'commit' && !commitment)}
                        className="bg-orange-500 hover:bg-orange-600 text-white"
                    >
                        {currentStepIndex < steps.length - 1 ? (
                            <>
                                Next
                                <ArrowRight className="size-4 ml-2" />
                            </>
                        ) : (
                            <>
                                {isProcessing ? 'Processing...' : 'Complete'}
                                <CheckCircle2 className="size-4 ml-2" />
                            </>
                        )}
                    </Button>
                </div>
            </motion.div>
        </div>
    );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mic, Image as ImageIcon, Link2, Clipboard, ChevronDown, Check, X } from 'lucide-react';
import { useDemoStore, PARACategory } from '@/store/demo-store';
import { cn } from '@/lib/utils';
import { useToast } from '../hooks/use-toast';

function classifyInput(text: string): { category: PARACategory; reason: string; label: string; icon: string; sub: string } {
    const lower = text.toLowerCase();

    if (/finish|complete|build|launch|create|deadline|by (monday|tuesday|wednesday|thursday|friday|saturday|sunday|jan|feb|mar|next week)|due|ship|deliver/.test(lower)) {
        return { category: 'projects', label: 'Projects', icon: '≡ƒôü', sub: 'Things with a finish line', reason: 'I detected a goal with a clear outcome ΓÇö this has a finish line.' };
    }
    if (/health|fitness|workout|exercise|finance|budget|money|savings|relationship|family|friend|career|work|job|learning|habit|routine|weekly|monthly/.test(lower)) {
        return { category: 'areas', label: 'Areas', icon: '≡ƒöä', sub: 'Ongoing responsibilities', reason: 'This sounds like an ongoing responsibility, not a one-time task.' };
    }
    if (/article|read|research|idea|note|reference|link|book|learn|interesting|thoughts on|how to|guide|template/.test(lower)) {
        return { category: 'resources', label: 'Resources', icon: '≡ƒôÜ', sub: 'Reference material', reason: 'This looks like reference material you\'ll want to come back to.' };
    }

    return { category: 'projects', label: 'Projects', icon: '≡ƒôü', sub: 'Things with a finish line', reason: 'Most captured items end up being actionable projects.' };
}

export function QuickCaptureModal() {
    const isOpen = useDemoStore(state => state.isCaptureOpen);
    const setCaptureOpen = useDemoStore(state => state.setCaptureOpen);
    const onClose = () => setCaptureOpen(false);

    const [content, setContent] = useState('');
    const [isReading, setIsReading] = useState(false);
    const [classification, setClassification] = useState<ReturnType<typeof classifyInput> | null>(null);
    const [isModifying, setIsModifying] = useState(false);
    const [isRecording, setIsRecording] = useState(false);
    const [animationState, setAnimationState] = useState<'idle' | 'confirming' | 'flying'>('idle');
    const fileInputRef = useRef<HTMLInputElement>(null);
    const addCapture = useDemoStore(state => state.addCapture);
    const { toast } = useToast();
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    const [prevIsOpenInternal, setPrevIsOpenInternal] = useState(isOpen);
    if (isOpen !== prevIsOpenInternal) {
        setPrevIsOpenInternal(isOpen);
        if (!isOpen) {
            setContent('');
            setClassification(null);
            setIsReading(false);
            setAnimationState('idle');
            setIsModifying(false);
        }
    }

    // Auto-focus on open
    useEffect(() => {
        if (isOpen && textareaRef.current) {
            setTimeout(() => textareaRef.current?.focus(), 100);
        }
    }, [isOpen]);

    // Typing debounce logic
        const words = content.trim().split(/\s+/).length;
        const hasUrl = /https?:\/\/[^\s]+/.test(content);

        if (words < 3 && !hasUrl) {
            setClassification(null);
            setIsReading(false);
            return;
        }

        const timer = setTimeout(() => {
            setIsReading(false);
            if (hasUrl) {
                setClassification({
                    category: 'resources',
                    label: 'Resources',
                    icon: '≡ƒôÜ',
                    sub: 'Reference material',
                    reason: 'I detected a URL ΓÇö this looks like a resource to save.'
                });
            } else {
                setClassification(classifyInput(content));
            }
        }, 500);

        return () => clearTimeout(timer);
    }, [content]);

    const handleVoiceToggle = () => {
        if (!isRecording) {
            setIsRecording(true);
            toast({ title: "Recording...", description: "Listening to your thoughts (Demo)" });
            // Simulate voice-to-text
            setTimeout(() => {
                setContent(prev => prev + (prev ? " " : "") + "Draft slide for the investor deck regarding traction.");
                setIsRecording(false);
                toast({ title: "Voice Captured", description: "Converted audio to text." });
            }, 3000);
        } else {
            setIsRecording(false);
        }
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setContent(prev => prev + (prev ? " " : "") + `[Attached Photo: ${file.name}]`);
            toast({ title: "Photo Attached", description: `${file.name} ready for classification.` });
        }
    };

    const handleConfirm = () => {
        if (!classification || animationState !== 'idle') return;

        setAnimationState('confirming');

        // Add to store
        addCapture({
            content,
            category: classification.label
        });

        // Trigger animations - Faster sequence
        setTimeout(() => {
            setAnimationState('flying');

            setTimeout(() => {
                toast({
                    title: `Added to ${classification.label} Γ£ô`,
                    description: content.length > 50 ? content.substring(0, 50) + '...' : content,
                    variant: 'default',
                    className: 'border-l-[3px] border-l-teal'
                });

                // Simulate Demo Intelligence Notification
                if (classification.category === 'projects') {
                    setTimeout(() => {
                        toast({
                            title: `≡ƒÆí Smart Connection`,
                            description: `This connects to 'Investor Pitch Deck' from 3 days ago.`,
                            variant: 'default',
                            className: 'border-l-[3px] border-l-accent'
                        });
                    }, 400);
                }

                onClose();
            }, 300);
        }, 150);
    };

    const categories = [
        { id: 'projects', label: 'Projects', icon: '≡ƒôü', sub: 'Things with a finish line', reason: 'Manually categorized as a project.' },
        { id: 'areas', label: 'Areas', icon: '≡ƒöä', sub: 'Ongoing responsibilities', reason: 'Manually categorized as an area.' },
        { id: 'resources', label: 'Resources', icon: '≡ƒôÜ', sub: 'Reference material', reason: 'Manually categorized as reference material.' },
    ];

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
            e.preventDefault();
            if (classification) handleConfirm();
        }
        if (e.key === 'Escape') {
            onClose();
        }
    };

    if (!isOpen && animationState === 'idle') return null;

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-zinc-900/25 backdrop-blur-[2px] z-50"
                        onClick={() => animationState === 'idle' && onClose()}
                    />

                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 pointer-events-none">
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95, y: 10 }}
                            animate={
                                animationState === 'idle' ? { opacity: 1, scale: 1, y: 0 } :
                                    animationState === 'confirming' ? { scale: 0.9, opacity: 0.8 } :
                                        { scale: 0.1, x: -300, y: -200, opacity: 0 }
                            }
                            transition={{
                                type: animationState === 'idle' ? 'spring' : 'tween',
                                duration: animationState === 'flying' ? 0.4 : 0.2,
                                ease: animationState === 'flying' ? 'easeIn' : 'easeOut'
                            }}
                            className={cn(
                                "bg-card border border-border rounded-modal shadow-modal w-full max-w-[480px] overflow-hidden pointer-events-auto",
                                animationState !== 'idle' && "pointer-events-none"
                            )}
                            onClick={(e) => e.stopPropagation()}
                        >
                            {/* Header */}
                            <div className="p-4 flex items-center justify-between pointer-events-auto">
                                <span className="font-medium text-primary flex items-center gap-2 text-[13px]">
                                    <div className="w-2 h-2 rounded-full bg-accent" />
                                    Capture
                                </span>
                                <button
                                    onClick={onClose}
                                    className="p-1.5 hover:bg-hover text-text-muted hover:text-primary rounded-button transition-colors"
                                >
                                    <X size={16} />
                                </button>
                            </div>

                            {/* Main Input */}
                            <div className="px-4 pb-3">
                                <textarea
                                    ref={textareaRef}
                                    value={content}
                                    onChange={(e) => {
                                        setContent(e.target.value);
                                        if (e.target.value.trim().length > 0) {
                                            setIsReading(true);
                                            setClassification(null);
                                        }
                                    }}
                                    onKeyDown={handleKeyDown}
                                    placeholder="Type, paste, or speak..."
                                    className="w-full bg-transparent resize-none text-primary focus:outline-none min-h-[80px] text-[15px] leading-relaxed placeholder:text-text-placeholder"
                                />

                                {/* Quick Media Actions */}
                                <div className="flex items-center gap-2 mt-2 flex-wrap">
                                    <button 
                                        onClick={handleVoiceToggle}
                                        className={cn(
                                            "px-2.5 py-1.5 border rounded-button transition-colors flex items-center gap-1.5 text-[11px] font-semibold tracking-[0.02em]",
                                            isRecording 
                                                ? "bg-red-500/10 border-red-500/50 text-red-500 animate-pulse" 
                                                : "border-border text-text-muted hover:text-primary hover:bg-hover"
                                        )}
                                    >
                                        <Mic size={12} className={isRecording ? "animate-bounce" : ""} /> {isRecording ? "Recording..." : "Voice"}
                                    </button>
                                    <input 
                                        type="file" 
                                        ref={fileInputRef} 
                                        onChange={handleFileSelect} 
                                        className="hidden" 
                                        accept="image/*"
                                    />
                                    <button 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="px-2.5 py-1.5 border border-border rounded-button text-text-muted hover:text-primary hover:bg-hover transition-colors flex items-center gap-1.5 text-[11px] font-semibold tracking-[0.02em]"
                                    >
                                        <ImageIcon size={12} /> Photo
                                    </button>
                                    <button 
                                        onClick={() => {
                                            navigator.clipboard.readText().then(text => {
                                                if (text.startsWith('http')) {
                                                    setContent(text);
                                                    toast({ title: "Link Pasted", description: "URL detected and added to capture." });
                                                } else {
                                                    toast({ title: "Nothing to paste", description: "Clipboard doesn't contain a valid URL." });
                                                }
                                            });
                                        }}
                                        className="px-2.5 py-1.5 border border-border rounded-button text-text-muted hover:text-primary hover:bg-hover transition-colors flex items-center gap-1.5 text-[11px] font-semibold tracking-[0.02em]"
                                    >
                                        <Link2 size={12} /> Link
                                    </button>
                                </div>
                            </div>

                            {/* AI Reading Indicator & Classification */}
                            <AnimatePresence mode="wait">
                                {isReading && (
                                    <motion.div
                                        key="reading"
                                        initial={{ opacity: 0, height: 0 }}
                                        animate={{ opacity: 1, height: 'auto' }}
                                        exit={{ opacity: 0, height: 0 }}
                                        className="px-4 pb-4 flex items-center pointer-events-none"
                                    >
                                        <div className="flex items-center gap-2 text-text-muted text-[12px] font-medium">
                                            <div className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
                                            Reading context...
                                        </div>
                                    </motion.div>
                                )}

                                {!isReading && classification && (
                                    <motion.div
                                        key="classification"
                                        initial={{ opacity: 0, y: 10, height: 0 }}
                                        animate={{ opacity: 1, y: 0, height: 'auto' }}
                                        exit={{ opacity: 0, height: 0 }}
                                        className="px-4 pb-4"
                                    >
                                        <hr className="border-border mb-4 -mx-4" />

                                        {!isModifying ? (
                                            <div className="bg-card border border-border rounded-card p-3 shadow-sm flex items-start gap-3">
                                                <span className="text-xl mt-0.5">{classification.icon}</span>
                                                <div className="flex-1">
                                                    <div className="flex items-center justify-between mb-1">
                                                        <span className="text-[11px] font-semibold text-text-muted uppercase tracking-[0.06em]">
                                                            {classification.label}
                                                        </span>
                                                        <button 
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                setIsModifying(true);
                                                            }}
                                                            className="text-[11px] text-accent hover:text-accent-dark font-medium transition-colors flex items-center gap-1"
                                                        >
                                                            Modify <ChevronDown size={12} />
                                                        </button>
                                                    </div>
                                                    <div className="text-[13px] text-primary font-medium mb-1">
                                                        {classification.sub}
                                                    </div>
                                                    <div className="text-[12px] text-secondary leading-relaxed">
                                                        {classification.reason}
                                                    </div>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="space-y-2">
                                                <div className="flex items-center justify-between mb-1 px-1">
                                                    <span className="text-[11px] font-semibold text-text-muted uppercase tracking-[0.06em]">Switch Category</span>
                                                    <button onClick={() => setIsModifying(false)} className="text-[11px] text-text-muted hover:text-primary">Cancel</button>
                                                </div>
                                                <div className="grid grid-cols-1 gap-2">
                                                    {categories.map(cat => (
                                                        <button
                                                            key={cat.id}
                                                            onClick={() => {
                                                                setClassification({
                                                                    category: cat.id as PARACategory,
                                                                    label: cat.label,
                                                                    icon: cat.icon,
                                                                    sub: cat.sub,
                                                                    reason: cat.reason
                                                                });
                                                                setIsModifying(false);
                                                            }}
                                                            className={cn(
                                                                "flex items-center gap-3 p-3 rounded-card text-left transition-all border",
                                                                classification.category === cat.id 
                                                                    ? "bg-accent/5 border-accent text-accent" 
                                                                    : "bg-card border-border hover:border-accent/50 text-primary"
                                                            )}
                                                        >
                                                            <span className="text-lg">{cat.icon}</span>
                                                            <div className="flex-1">
                                                                <div className="text-[12px] font-bold">{cat.label}</div>
                                                                <div className="text-[10px] opacity-70">{cat.sub}</div>
                                                            </div>
                                                            {classification.category === cat.id && <Check size={14} />}
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>
                                        )}

                                        <div className="flex justify-end mt-4">
                                            <button
                                                onClick={handleConfirm}
                                                className="flex items-center gap-1.5 px-4 py-2 text-[13px] font-semibold text-white bg-accent hover:bg-accent-dark transition-colors rounded-button shadow-sm"
                                            >
                                                <Check size={14} /> Confirm
                                            </button>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            {/* Footer */}
                            <div className="bg-subtle text-center py-2.5 border-t border-border mt-auto">
                                <span className="text-[11px] text-text-muted">
                                    <kbd className="font-mono text-text-secondary bg-card border border-border rounded px-1.5 py-0.5 text-[9px] shadow-sm ml-1">Cmd</kbd> + <kbd className="font-mono text-text-secondary bg-card border border-border rounded px-1.5 py-0.5 text-[9px] shadow-sm">Enter</kbd> to confirm ┬╖ <kbd className="font-mono text-text-secondary bg-card border border-border rounded px-1.5 py-0.5 text-[9px] shadow-sm ml-1">Esc</kbd> to close
                                </span>
                            </div>
                        </motion.div>
                    </div>
                </>
            )}
        </AnimatePresence>
    );
}

'use client';

import { FileText, Lightbulb, StickyNote, BookOpen } from 'lucide-react';
import { cn } from '@/lib/utils';

type QuickType = 'task' | 'idea' | 'note' | 'reference';

interface QuickTypeChipsProps {
    onSelect: (type: QuickType) => void;
    selected?: QuickType;
}

const typeConfig: Record<QuickType, { label: string; icon: any; color: string; shortcut: string }> = {
    task: { label: 'Task', icon: FileText, color: 'text-blue-400', shortcut: 'T' },
    idea: { label: 'Idea', icon: Lightbulb, color: 'text-yellow-400', shortcut: 'I' },
    note: { label: 'Note', icon: StickyNote, color: 'text-green-400', shortcut: 'N' },
    reference: { label: 'Reference', icon: BookOpen, color: 'text-purple-400', shortcut: 'R' },
};

export function QuickTypeChips({ onSelect, selected }: QuickTypeChipsProps) {
    return (
        <div className="flex items-center gap-2 flex-wrap">
            {Object.entries(typeConfig).map(([type, config]) => {
                const Icon = config.icon;
                const isSelected = selected === type;
                return (
                    <button
                        key={type}
                        onClick={() => onSelect(type as QuickType)}
                        className={cn(
                            "flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all",
                            isSelected
                                ? "bg-white/10 border border-primary/50 text-white"
                                : "bg-white/5 border border-white/10 text-neutral-400 hover:bg-white/10 hover:text-white"
                        )}
                    >
                        <Icon className={cn("size-3.5", isSelected ? config.color : "text-neutral-500")} />
                        <span>{config.label}</span>
                        <kbd className={cn(
                            "px-1.5 py-0.5 rounded text-[10px] font-mono",
                            isSelected ? "bg-primary/20 text-primary" : "bg-white/5 text-neutral-500"
                        )}>
                            {config.shortcut}
                        </kbd>
                    </button>
                );
            })}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { CheckCircle2, Clock, Zap, X, Plus } from 'lucide-react';
import { useTodayList, TodayAction } from '@/hooks/useTodayList';
import { cn } from '@/lib/utils';
import { Button } from './ui/Button';
import { motion, AnimatePresence } from 'framer-motion';

export function TodayList() {
    const { todayActions, removeFromToday, clearToday } = useTodayList();
    const [isExpanded, setIsExpanded] = useState(true);

    if (todayActions.length === 0) return null;

    const totalTime = todayActions.reduce((sum, a) => sum + a.timeEstimate, 0);
    const highPriority = todayActions.filter(a => a.priority === 'high').length;

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="glass-panel border border-[#ffdea5] rounded-xl p-4 mb-6 shadow-sm"
        >
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <h3 className="text-lg font-bold text-[#461704]">Today&apos;s Plan</h3>
                    <span className="text-sm text-[#82330c]">
                        {todayActions.length} action{todayActions.length !== 1 ? 's' : ''} ΓÇó {totalTime}m
                    </span>
                    {highPriority > 0 && (
                        <span className="text-xs px-2 py-0.5 rounded bg-red-500/20 text-red-600">
                            {highPriority} high
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        onClick={clearToday}
                        variant="ghost"
                        size="sm"
                        className="text-xs text-[#82330c] hover:text-[#461704]"
                    >
                        Clear
                    </Button>
                    <button
                        onClick={() => setIsExpanded(!isExpanded)}
                        className="p-1 hover:bg-[#ffdea5]/30 rounded transition-colors"
                    >
                        <X className={cn("size-4 text-[#82330c] transition-transform", isExpanded && "rotate-45")} />
                    </button>
                </div>
            </div>

            <AnimatePresence>
                {isExpanded && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                    >
                        <div className="space-y-2 pt-2">
                            {todayActions.map((action) => (
                                <TodayActionItem
                                    key={action.id}
                                    action={action}
                                    onRemove={() => removeFromToday(action.id)}
                                />
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
}

function TodayActionItem({ action, onRemove }: { action: TodayAction; onRemove: () => void }) {
    const priorityColors = {
        high: 'border-red-500/30 bg-red-500/5',
        medium: 'border-[#ffdea5] bg-white/50',
        low: 'border-neutral-200 bg-neutral-50/50',
    };

    const energyIcons = {
        low: '≡ƒƒó',
        medium: '≡ƒƒí',
        high: '≡ƒö┤',
    };

    return (
        <motion.div
            layout
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className={cn(
                "flex items-center gap-3 p-3 rounded-lg border transition-all",
                priorityColors[action.priority]
            )}
        >
            <div className="size-5 rounded border border-[#ffdea5] flex items-center justify-center shrink-0">
                <CheckCircle2 className="size-3 text-[#ffdea5] opacity-0 group-hover:opacity-100" />
            </div>
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-0.5">
                    <span className="font-medium text-[#461704] truncate text-sm">{action.title}</span>
                    <span className="text-[10px]" title={`Energy level: ${action.energyLevel}`}>
                        {energyIcons[action.energyLevel]}
                    </span>
                </div>
                <div className="flex items-center gap-3 text-[10px] text-[#82330c]">
                    <span className="flex items-center gap-1">
                        <Clock className="size-2.5" />
                        {action.timeEstimate}m
                    </span>
                    {action.dueDate && (
                        <span>Due: {new Date(action.dueDate).toLocaleDateString()}</span>
                    )}
                </div>
            </div>
            <button
                onClick={onRemove}
                className="p-1 hover:bg-[#ffdea5]/30 rounded text-[#82330c] hover:text-red-500 transition-colors"
                title="Remove from Today"
            >
                <X className="size-3" />
            </button>
        </motion.div>
    );
}

'use client';

import { useState } from 'react';
import { Sparkles, Loader2, CheckCircle2, X, ArrowRight, Zap } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { AgenticProcessor, ProcessedItem, BatchCluster } from '@/services/agenticProcessor';
import { useNeyroStore } from '@mobile/store/useNeyroStore';
import { useTodayList } from '@/hooks/useTodayList';
import { Button } from './ui/Button';
import { cn } from '@/lib/utils';

interface AgenticProcessorProps {
    items: Array<{ id: string; content: string; createdAt: number }>;
    onComplete: (results?: any) => void;
}

export function AgenticProcessor({ items, onComplete }: AgenticProcessorProps) {
    const [isProcessing, setIsProcessing] = useState(false);
    const [step, setStep] = useState<'idle' | 'processing' | 'review' | 'applying'>('idle');
    const [results, setResults] = useState<{
        processedItems: ProcessedItem[];
        batches: BatchCluster[];
        suggestedTodayActions: any[];
    } | null>(null);
    const [approvedItems, setApprovedItems] = useState<Set<string>>(new Set());
    const [approvedBatches, setApprovedBatches] = useState<Set<number>>(new Set());

    // @ts-ignore
    const classifyItem = useNeyroStore((state: any) => state.classifyItem);
    // @ts-ignore
    const addProject = useNeyroStore((state: any) => state.addProject);
    // @ts-ignore
    const loadData = useNeyroStore((state: any) => state.loadData);
    const { addToToday } = useTodayList();

    const handleProcess = async () => {
        setIsProcessing(true);
        setStep('processing');

        try {
            const result = await AgenticProcessor.processInbox(items);
            setResults(result);
            setStep('review');
        } catch (error) {
            console.error('Processing failed:', error);
            setStep('idle');
        } finally {
            setIsProcessing(false);
        }
    };

    const handleApply = async () => {
        if (!results) return;

        setStep('applying');

        try {
            // Apply approved items
            for (const item of results.processedItems) {
                if (approvedItems.has(item.id)) {
                    await classifyItem(item.id, item.suggestedDestination, item.suggestedTargetId);
                }
            }

            // Apply approved batches
            for (let i = 0; i < results.batches.length; i++) {
                if (approvedBatches.has(i)) {
                    const batch = results.batches[i];
                    if (batch.suggestedAction === 'create_project' && batch.projectTitle) {
                        await addProject(batch.projectTitle, batch.projectDescription);
                    }
                }
            }

            // Add suggested today actions to Today list
            if (results.suggestedTodayActions) {
                for (const action of results.suggestedTodayActions) {
                    const item = results.processedItems.find((p: ProcessedItem) => p.id === action.itemId);
                    if (item) {
                        addToToday({
                            id: `today_${action.itemId}_${Date.now()}`,
                            title: action.title || item.title,
                            priority: action.priority,
                            timeEstimate: action.timeEstimate || item.timeEstimate || 30,
                            energyLevel: action.energyLevel || item.energyLevel || 'medium',
                            sourceType: 'inbox',
                            sourceId: action.itemId,
                            dueDate: item.dueDate,
                            tags: item.tags,
                        });
                    }
                }
            }

            await loadData();
            onComplete(results);
        } catch (error) {
            console.error('Apply failed:', error);
        }
    };

    if (step === 'idle') {
        return (
            <Button
                onClick={handleProcess}
                className="bg-orange-500 hover:bg-orange-600 text-white font-bold px-6 py-3"
            >
                <Sparkles className="size-5 mr-2" />
                Auto Process with AI
            </Button>
        );
    }

    if (step === 'processing') {
        return (
            <div className="bg-[#1C1C1E] border border-white/10 rounded-xl p-6">
                <div className="flex items-center gap-3">
                    <Loader2 className="size-6 text-primary animate-spin" />
                    <div>
                        <h3 className="text-lg font-bold text-white">AI is analyzing your inbox...</h3>
                        <p className="text-sm text-neutral-400">Clustering items, suggesting actions, and planning your day</p>
                    </div>
                </div>
            </div>
        );
    }

    if (step === 'review' && results) {
        return (
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-xl font-bold text-white">Review AI Suggestions</h3>
                    <Button
                        onClick={handleApply}
                        disabled={approvedItems.size === 0 && approvedBatches.size === 0}
                        className="bg-orange-500 hover:bg-orange-600 text-white"
                    >
                        Apply {approvedItems.size + approvedBatches.size} Changes
                    </Button>
                </div>

                {/* Batches */}
                {results.batches.length > 0 && (
                    <div>
                        <h4 className="text-lg font-semibold text-white mb-3">Batched Items</h4>
                        <div className="space-y-3">
                            {results.batches.map((batch, i) => (
                                <BatchCard
                                    key={i}
                                    batch={batch}
                                    items={items}
                                    isApproved={approvedBatches.has(i)}
                                    onToggle={() => {
                                        const newSet = new Set(approvedBatches);
                                        if (newSet.has(i)) {
                                            newSet.delete(i);
                                        } else {
                                            newSet.add(i);
                                        }
                                        setApprovedBatches(newSet);
                                    }}
                                />
                            ))}
                        </div>
                    </div>
                )}

                {/* Processed Items */}
                <div>
                    <h4 className="text-lg font-semibold text-white mb-3">Individual Items</h4>
                    <div className="space-y-3">
                        {results.processedItems.map((item) => (
                            <ProcessedItemCard
                                key={item.id}
                                item={item}
                                isApproved={approvedItems.has(item.id)}
                                onToggle={() => {
                                    const newSet = new Set(approvedItems);
                                    if (newSet.has(item.id)) {
                                        newSet.delete(item.id);
                                    } else {
                                        newSet.add(item.id);
                                    }
                                    setApprovedItems(newSet);
                                }}
                            />
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (step === 'applying') {
        return (
            <div className="bg-[#1C1C1E] border border-white/10 rounded-xl p-6">
                <div className="flex items-center gap-3">
                    <Loader2 className="size-6 text-primary animate-spin" />
                    <div>
                        <h3 className="text-lg font-bold text-white">Applying changes...</h3>
                        <p className="text-sm text-neutral-400">Updating your system</p>
                    </div>
                </div>
            </div>
        );
    }

    return null;
}

