export interface AgentProcessingResult {
    processedItems: ProcessedItem[];
    batches: BatchCluster[];
    suggestedTodayActions: Array<{
        itemId: string;
        title: string;
        priority: 'high' | 'medium' | 'low';
        timeEstimate: number;
        energyLevel: 'low' | 'medium' | 'high';
